**2) Apps Script**

```javascript
function markSuperseded() {
  const EMAIL_COL = 3;  // C: raw email
  const TIME_COL = 9;   // I: cleaned timestamp
  const OUT_COL = 15;   // O: output (clear the O formula first)

  const sheet = SpreadsheetApp.getActiveSheet();
  const last = sheet.getLastRow();
  if (last < 2) return;
  const n = last - 1;

  const emails = sheet.getRange(2, EMAIL_COL, n, 1).getValues();
  const times = sheet.getRange(2, TIME_COL, n, 1).getValues();

  const toNum = v => v instanceof Date ? v.getTime()
                   : (typeof v === 'number' ? v : NaN);
  const keyOf = v => String(v).trim().toLowerCase();

  // Find the row to keep for each email: latest time, ties keep the first (lowest row)
  const keep = {};
  for (let i = 0; i < n; i++) {
    const key = keyOf(emails[i][0]);
    const t = toNum(times[i][0]);
    if (!key || isNaN(t)) continue;
    if (!(key in keep) || t > toNum(times[keep[key]][0])) keep[key] = i;
  }

  const out = emails.map((r, i) => {
    const key = keyOf(r[0]);
    const t = toNum(times[i][0]);
    if (!key || isNaN(t)) return [''];
    return [keep[key] === i ? '' : 'SUPERSEDED'];
  });

  sheet.getRange(2, OUT_COL, n, 1).setValues(out);
}
```

Notes:
- Use either the formula or the script for column O, not both. The script overwrites whatever is there with static values, so you'd need to re-run it when new rows arrive. If you want to keep the formula, change `OUT_COL` to an empty column.
- It reads timestamps from column I (your cleaned column), so Step 3 needs to have run. Rows where I is `REVIEW` are skipped.
- The comparison is strict `>`, which is what makes ties keep the first row.

