  const toNum = v => v instanceof Date ? v.getTime()
                   : (typeof v === 'number' ? v : NaN);
  const keyOf = v => String(v).trim().toLowerCase();

  // Find the row to keep for each email: latest time; ties keep the LAST (lowest on sheet) row
  const keep = {};
  for (let i = 0; i < n; i++) {
    const key = keyOf(emails[i][0]);
    const t = toNum(times[i][0]);
    if (!key || isNaN(t)) continue;
    if (!(key in keep) || t >= toNum(times[keep[key]][0])) keep[key] = i;
  }

  const out = emails.map((r, i) => {
    const key = keyOf(r[0]);
    const t = toNum(times[i][0]);
    if (!key || isNaN(t)) return [''];
    return [keep[key] === i ? '' : 'SUPERSEDED'];
  });

  sheet.getRange(2, OUT_COL, n, 1).setValues(out);
}
```

The only change is `>` to `>=` in the comparison. Because rows are scanned top to bottom, a later row with an equal timestamp now replaces the earlier one as the keeper.

